// Accepts one detection or a batch: { "detections": [ ... ] }
// Rejects bad rows instead of crashing the workflow.
const body = $input.first().json.body ?? $input.first().json;
const list = Array.isArray(body.detections) ? body.detections : [body];
const num = v => (v === undefined || v === null || v === '') ? null : Number(v);

const ok = [], bad = [];
for (const d of list) {
  const conf = num(d.confidence);
  const errors = [];
  if (!d.class) errors.push('class missing');
  if (conf === null || isNaN(conf) || conf < 0 || conf > 1) errors.push('confidence must be 0..1');
  if (errors.length) { bad.push({ input: d, errors }); continue; }
  ok.push({
    run_code: d.run_code ?? body.run_code ?? null,
    frame_id: num(d.frame_id),
    box_id: d.box_id ?? null,
    class: String(d.class),
    confidence: conf,
    x: num(d.x), y: num(d.y), w: num(d.w), h: num(d.h),
    model_version: d.model_version ?? body.model_version ?? 'unknown',
  });
}
if (!ok.length) throw new Error('No valid detections: ' + JSON.stringify(bad));
// keep rejected rows visible in the execution log
if (bad.length) console.log('Rejected rows:', JSON.stringify(bad));
return ok.map(row => ({ json: row }));
